        public IReadOnlyDictionary<string, double> GetMetrics() => _metrics;

        public IReadOnlyList<double[]> GetHistory(int lastN = 100)
            => _history.TakeLast(lastN).ToList();

        public async Task SaveStateAsync(string path, CancellationToken ct = default)
        {
            var state = new { Step = _step, Metrics = _metrics, Config = _config };
            var json = JsonSerializer.Serialize(state, new JsonSerializerOptions { WriteIndented = true });
            await File.WriteAllTextAsync(path, json, ct).ConfigureAwait(false);
        }

        public async Task LoadStateAsync(string path, CancellationToken ct = default)
        {
            var json = await File.ReadAllTextAsync(path, ct).ConfigureAwait(false);
            using var doc = JsonDocument.Parse(json);
            _step = doc.RootElement.GetProperty("Step").GetInt64();
        }

        public void Reset()
        {
            Interlocked.Exchange(ref _step, 0);
            _metrics.Clear();
            _history.Clear();
        }

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            _cts.Cancel();
            _cts.Dispose();
            _semaphore.Dispose();
            GC.SuppressFinalize(this);
        }

        public override string ToString()
            => $"priority_samplerComponent4(Step={_step}, Metrics={_metrics.Count}, NodeId={_config.NodeId})";
    }

    /// <summary>
    /// priority_samplerComponent5 — component 5 of the Replay.Sampler pipeline.
    /// Implements quantum-classical hybrid processing for the AGI mesh.
    /// Integrates with MAIA-300, EWC, replay buffer, and WebTransport.
    /// </summary>
    public sealed class priority_samplerComponent5 : IDisposable
    {
        private readonly priority_samplerConfig _config;
        private readonly ILogger<priority_samplerComponent5> _logger;
        private readonly SemaphoreSlim _semaphore = new(1, 1);
        private readonly ConcurrentQueue<Dictionary<string, object>> _eventQueue = new();
        private readonly ConcurrentDictionary<string, double> _metrics = new();
        private readonly List<double[]> _history = new();
        private long _step;
        private bool _disposed;
        private readonly CancellationTokenSource _cts = new();

        public priority_samplerComponent5(priority_samplerConfig? config = null, ILogger<priority_samplerComponent5>? logger = null)
        {
